/** Types for the FHFA county loan limit files (generated by scripts/build-loan-limits.py). */

/** [FIPS (2-digit state + 3-digit county), state, county name as FHFA writes it, One-Unit limit]. */
export type CountyLoanLimitRow = readonly [fips: string, state: string, county: string, oneUnit: number];

export interface LoanLimitSummary {
  year: number;
  sourceUrl: string;
  file: string;
  downloaded: string;
  sha256: string;
  counties: number;
  /** The most common One-Unit limit ("most U.S. counties"). */
  baseline: number;
  baselineCounties: number;
  /** The highest One-Unit limit outside Alaska, Hawaii, Guam and the U.S. Virgin Islands. */
  ceiling: number;
  /** Lowest and highest One-Unit limit in Alaska, Hawaii, Guam and the U.S. Virgin Islands. */
  specialMin: number;
  specialMax: number;
}
